import React from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
  useMediaQuery,
  Avatar,
} from '@mui/material';
import { IUserDetailsData } from '../../../core/Interface/user.interface';
import { theme } from '../../../theme';
import { useTranslation } from 'react-i18next';
import { formatUtcToTime } from '../../../core/utils';

interface ViewUserListDataProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  data?: IUserDetailsData;
}

const ViewUserDetails: React.FC<ViewUserListDataProps> = ({
  open,
  setOpen,
  data,
}) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { t } = useTranslation(['usermanage']);
  const handleCloseDialog = () => {
    setOpen(false);
  };

  return (
    <Dialog
      aria-labelledby="user-list-data-title"
      fullScreen={isMobile}
      fullWidth
      maxWidth="sm"
      onClose={handleCloseDialog}
      open={open}
    >
      <DialogTitle
        id="user-list-data-title"
        sx={{
          fontWeight: 600,
          background: '#CFD8DC',
          borderRadius: 1,
          padding: '16px 24px',
        }}
      >
        User Details
      </DialogTitle>
      <DialogContent
        sx={{
          display: 'grid',
          gridTemplateColumns: 'auto 10px auto',
          gap: 1,
          alignItems: 'center',
          padding: '10px 20px',
          mt: 2,
        }}
      >
        {data ? (
          <>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              <strong>{t('usermanage:title.username')}</strong>
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18, textAlign: 'center' }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              color="text.secondary"
              variant="body1"
            >
              <strong>{data.username}</strong>
            </Typography>

            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {t('usermanage:title.firstname')}
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {data.firstname}
            </Typography>

            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {t('usermanage:title.lastname')}
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {data.lastname}
            </Typography>

            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {t('usermanage:title.email')}
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {data.email}
            </Typography>

            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {t('usermanage:title.mobile')}
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {data.mobile}
            </Typography>

            {data.company?.name && (
              <>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.companyName')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {data.company.name}
                </Typography>
              </>
            )}

            {data.branch?.name && (
              <>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.branchName')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {data.branch.name}
                </Typography>
              </>
            )}

            {data.createdBy && (
              <>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.createdBy')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {data.createdBy}
                </Typography>
              </>
            )}
            {data.updatedBy && (
              <>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.updatedBy')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {data.updatedBy}
                </Typography>
              </>
            )}
            {data.createdDate && (
              <>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.createdDate')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {formatUtcToTime(data.createdDate)}
                </Typography>
              </>
            )}
            {data.updatedDate && (
              <>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.updatedDate')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {formatUtcToTime(data.updatedDate)}
                </Typography>

                <Typography
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                  variant="body1"
                >
                  {t('usermanage:title.upload image')}
                </Typography>
                <Typography
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                  variant="body1"
                >
                  :
                </Typography>
                <Avatar
                  alt={data.username}
                  src={data.imageUrl}
                  sx={{ width: 80, height: 80, borderRadius: '50%' }}
                />
              </>
            )}
          </>
        ) : (
          <Typography variant="body1">No User data available</Typography>
        )}
      </DialogContent>
      <DialogActions sx={{ padding: '16px 24px' }}>
        <Button
          color="primary"
          onClick={handleCloseDialog}
          sx={{
            width: 200,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ViewUserDetails;
