import React, { CSSProperties, useEffect, useMemo, useState } from 'react';
import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import {
  IUserDetails,
  IUserDetailsData,
  IPrivileges,
} from '../../core/Interface/user.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import {
  useGetAllUserManageQuery,
} from '../posApi';
import useUserListColumn from './useUserListColumn';

const useUserList = (
  handleEdit: (data: IUserDetailsData) => void,
  handleResetPassword: (data: IUserDetailsData) => void,
  handleDelete: (data: IUserDetailsData) => void,
  viewUserDetailsPopUp: (id: string) => void,
  handlePrivilegeData?: (data: IPrivileges[]) => void,
  handlePaginationChangePage?: (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number) => void,
) => {
  const { page } = usePageQuery();
  const [popUpUserId, setPopUpUserId] = useState<string>('');
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const [debouncedSearch, setDebouncedSearch] = useState('');

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchText);
      setPagination((prev) => ({ ...prev, pageIndex: 0 }));
    }, 500);
    return () => clearTimeout(timer);
  }, [searchText]);


  const {
    data: userListData,
    isLoading,
    isFetching,
    error: fetchError,
  } = useGetAllUserManageQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText: debouncedSearch,
  });

  const userListMemo = useMemo(() => {
    return userListData?.data as IUserDetails;
  }, [userListData?.data]);

  const records = userListMemo?.records ?? [];

  const columns = useUserListColumn({
    handleEdit,
    handleDelete,
    handleResetPassword,
    viewUserDetailsPopUp,
    handlePrivilegeData,
  });

  const shouldShowField = (field: 'company' | 'branch'): boolean =>
    records.some((item) => item[field] != null);

  const showCompany = shouldShowField('company');
  const showBranch = shouldShowField('branch');

  const columnVisibility = useMemo(
    () => ({
      id: false,
      company: showCompany,
      branch: showBranch,
    }),
    [showCompany, showBranch]
  );

  const table = useReactTable({
    data: fetchError ? [] : records,
    columns: columns,
    initialState: {
      columnVisibility,
    },
    meta: {
      getRowStyles: (row: Row<IUserDetailsData>): CSSProperties => ({}),
    },
    pageCount: userListMemo?.totalRecords ?? 0,
    state: {
      pagination,
      columnVisibility,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error: fetchError,
    totalCount: userListMemo?.totalRecords ?? 0,
    popUpUserId,
    searchText,
    setSearchText,
    setPopUpUserId,
  };
};

export default useUserList;
