import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import IconButton from '@mui/material/IconButton';
import InputAdornment from '@mui/material/InputAdornment';
import {
  Box,
  CircularProgress,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import LockResetOutlinedIcon from '@mui/icons-material/LockResetOutlined';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import CheckCircleOutlinedIcon from '@mui/icons-material/CheckCircleOutlined';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useTranslation } from 'react-i18next';
import * as Yup from 'yup';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useChangePasswordMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';

interface IPassword {
  openModel?: boolean;
  handleCloseDialog: (close: boolean) => void;
  userId: string | undefined;
}

const INPUT_ROOT_BASE = {
  borderRadius: '10px',
  backgroundColor: '#F8FAFC',
  '& fieldset': { borderColor: '#CBD5E1', borderWidth: '1.5px' },
  '&:hover fieldset': { borderColor: '#2563EB' },
  '&.Mui-focused': {
    backgroundColor: '#fff',
    '& fieldset': { borderColor: '#2563EB', borderWidth: '2px' },
  },
  '&.Mui-error fieldset': { borderColor: '#dc2626' },
};

const FIELD_SX = {
  width: '100%',
  '& .MuiOutlinedInput-root': INPUT_ROOT_BASE,
  '& .MuiInputBase-input': {
    fontSize: '0.9rem',
    padding: '12px 14px 12px 0',
  },
};

const ChangePassword = ({
  openModel = false,
  handleCloseDialog,
  userId,
}: IPassword) => {
  const { t } = useTranslation(['common', 'usermanage']);
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [changePassword, { isLoading }] = useChangePasswordMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const [showNew, setShowNew] = React.useState(false);
  const [showConfirm, setShowConfirm] = React.useState(false);

  const handleClose = () => handleCloseDialog(false);

  const ChangePasswordSchema = Yup.object().shape({
    newPassword: Yup.string().required('Please enter your new password'),
    confirmPassword: Yup.string()
      .required('Please retype your password.')
      .oneOf([Yup.ref('newPassword')], 'Your passwords do not match.'),
  });

  const formik = useFormik({
    initialValues: { newPassword: null as string | null, confirmPassword: null as string | null },
    onSubmit: async (values) => {
      try {
        const passwordResponse = await changePassword({ userId, newPassword: values.newPassword }).unwrap();
        if (!passwordResponse.status) {
          showErrorMessage(passwordResponse.data as string);
        } else {
          handleClose();
          showMessage(passwordResponse.data as string);
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
    validationSchema: ChangePasswordSchema,
  });

  const passwordsMatch =
    !!formik.values.newPassword &&
    !!formik.values.confirmPassword &&
    formik.values.newPassword === formik.values.confirmPassword;

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="reset-password-dialog"
          fullScreen={isMobile}
          fullWidth
          maxWidth="xs"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '14px', overflow: 'hidden' } }}
        >
          {/* Header */}
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2.5, position: 'relative', overflow: 'hidden' }}>
              <Box sx={{ background: 'rgba(255,255,255,0.06)', borderRadius: '50%', height: 140, pointerEvents: 'none', position: 'absolute', right: -40, top: -60, width: 140 }} />
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', border: '1px solid rgba(255,255,255,0.2)', borderRadius: '10px', display: 'flex', flexShrink: 0, height: 42, justifyContent: 'center', width: 42 }}>
                  <LockResetOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                    {t('usermanage:resetYourPassword')}
                  </Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: '0.72rem', fontWeight: 500, mt: 0.25 }}>
                    Choose a strong new password
                  </Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>

          {/* Content */}
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <Stack spacing={2.5}>
              {/* New Password */}
              <Box>
                <Typography sx={{ color: alpha('#142352', 0.7), fontSize: '0.78rem', fontWeight: 700, letterSpacing: '0.04em', mb: 0.75, textTransform: 'uppercase' }}>
                  {t('usermanage:newPassword')}
                </Typography>
                <TextField
                  autoComplete="new-password"
                  error={!!(formik.touched.newPassword && formik.errors.newPassword)}
                  helperText={formik.touched.newPassword && formik.errors.newPassword
                    ? <span style={{ textTransform: 'none' }}>{formik.errors.newPassword}</span>
                    : null}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <LockOutlinedIcon sx={{ color: alpha('#142352', 0.35), fontSize: 18 }} />
                      </InputAdornment>
                    ),
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton edge="end" onClick={() => setShowNew((p) => !p)} size="small" tabIndex={-1}>
                          {showNew
                            ? <VisibilityOff sx={{ fontSize: 18, color: alpha('#142352', 0.4) }} />
                            : <Visibility sx={{ fontSize: 18, color: alpha('#142352', 0.4) }} />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  placeholder="Enter new password"
                  size="small"
                  sx={FIELD_SX}
                  type={showNew ? 'text' : 'password'}
                  {...formik.getFieldProps('newPassword')}
                />
              </Box>

              {/* Confirm Password */}
              <Box>
                <Typography sx={{ color: alpha('#142352', 0.7), fontSize: '0.78rem', fontWeight: 700, letterSpacing: '0.04em', mb: 0.75, textTransform: 'uppercase' }}>
                  {t('usermanage:confirmPassword')}
                </Typography>
                <TextField
                  autoComplete="new-password"
                  error={!!(formik.touched.confirmPassword && formik.errors.confirmPassword)}
                  helperText={formik.touched.confirmPassword && formik.errors.confirmPassword
                    ? <span style={{ textTransform: 'none' }}>{formik.errors.confirmPassword}</span>
                    : null}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <LockOutlinedIcon sx={{ color: alpha('#142352', 0.35), fontSize: 18 }} />
                      </InputAdornment>
                    ),
                    endAdornment: (
                      <InputAdornment position="end">
                        {passwordsMatch ? (
                          <CheckCircleOutlinedIcon sx={{ color: '#16a34a', fontSize: 18 }} />
                        ) : (
                          <IconButton edge="end" onClick={() => setShowConfirm((p) => !p)} size="small" tabIndex={-1}>
                            {showConfirm
                              ? <VisibilityOff sx={{ fontSize: 18, color: alpha('#142352', 0.4) }} />
                              : <Visibility sx={{ fontSize: 18, color: alpha('#142352', 0.4) }} />}
                          </IconButton>
                        )}
                      </InputAdornment>
                    ),
                  }}
                  placeholder="Re-enter new password"
                  size="small"
                  sx={passwordsMatch ? {
                    ...FIELD_SX,
                    '& .MuiOutlinedInput-root': {
                      ...INPUT_ROOT_BASE,
                      '& fieldset': { borderColor: '#16a34a', borderWidth: '1.5px' },
                      '&:hover fieldset': { borderColor: '#16a34a' },
                    },
                  } : FIELD_SX}
                  type={showConfirm ? 'text' : 'password'}
                  {...formik.getFieldProps('confirmPassword')}
                />
              </Box>

              {/* Password match hint */}
              {passwordsMatch && (
                <Box sx={{ alignItems: 'center', background: alpha('#16a34a', 0.07), border: `1px solid ${alpha('#16a34a', 0.2)}`, borderRadius: '8px', display: 'flex', gap: 1, px: 1.5, py: 1 }}>
                  <CheckCircleOutlinedIcon sx={{ color: '#16a34a', fontSize: 16 }} />
                  <Typography sx={{ color: '#16a34a', fontSize: '0.78rem', fontWeight: 600 }}>
                    Passwords match
                  </Typography>
                </Box>
              )}
            </Stack>
          </DialogContent>

          {/* Actions */}
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                borderColor: '#CBD5E1',
                borderRadius: '8px',
                color: '#475569',
                fontWeight: 600,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formik.isValid || Object.keys(formik.touched).length === 0 || isLoading}
              onClick={() => formik.handleSubmit()}
              sx={{
                background: HEADER_GRADIENT,
                borderRadius: '8px',
                boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
                color: '#fff',
                fontWeight: 700,
                height: 40,
                minWidth: 130,
                px: 3,
                textTransform: 'none',
                '&:hover': { opacity: 0.9 },
                '&.Mui-disabled': { background: '#CBD5E1', boxShadow: 'none', color: '#94A3B8' },
              }}
              type="submit"
              variant="contained"
            >
              {isLoading
                ? <CircularProgress size={16} sx={{ color: '#fff' }} />
                : t('common:reset')}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(ChangePassword);
